gME(){return"\u0986\u09aa\u09a8\u09bf \u09aa\u09cd\u09b0\u0995\u09c3\u09a4\u09aa\u0995\u09cd\u09b7\u09c7 \u09af\u09c7 \u09a8\u09be\u09ae\u09af\u09c1\u0995\u09cd\u09a4 \u0985\u09cd\u09af\u09be\u0995\u09be\u0989\u09a8\u09cd\u099f\u0997\u09c1\u09b2\u09cb\u09a4\u09c7 \u09ac\u09cd\u09af\u09be\u0982\u0995\u09bf\u0982 \u0995\u09b0\u09c7\u09a8 \u09a4\u09be \u09aa\u09b0\u09bf\u099a\u09be\u09b2\u09a8\u09be \u0995\u09b0\u09c1\u09a8"},
gN8(){return"\u09a6\u09c8\u09a8\u09a8\u09cd\u09a6\u09bf\u09a8 \u09b8\u09be\u09ae\u09be\u09a8\u09cd\u09af \u0996\u09b0\u099a\u09c7\u09b0 \u099c\u09a8\u09cd\u09af \u099b\u09cb\u099f \u09a8\u0997\u09a6 \u09ab\u09cd\u09b2\u09cb\u099f"},
gMA(){return"\u0985\u09cd\u09af\u09be\u0995\u09be\u0989\u09a8\u09cd\u099f\u09c7\u09b0 \u09ae\u09a7\u09cd\u09af\u09c7 \u09b8\u09cd\u09a5\u09be\u09a8\u09be\u09a8\u09cd\u09a4\u09b0"},
gMB(){return"\u09a8\u0997\u09a6, \u09ac\u09cd\u09af\u09be\u0982\u0995 \u0985\u09cd\u09af\u09be\u0995\u09be\u0989\u09a8\u09cd\u099f \u098f\u09ac\u0982 \u09aa\u09c7\u099f\u09bf \u0995\u09cd\u09af\u09be\u09b6\u09c7\u09b0 \u09ae\u09a7\u09cd\u09af\u09c7 \u0985\u09b0\u09cd\u09a5 \u09b8\u09cd\u09a5\u09be\u09a8\u09be\u09a8\u09cd\u09a4\u09b0 \u0995\u09b0\u09c1\u09a8"},
gN7(){return"\u098f\u0995\u099f\u09bf \u09b8\u09ae\u09af\u09bc\u0995\u09be\u09b2 \u09ac\u09a8\u09cd\u09a7 \u0995\u09b0\u09c1\u09a8 \u09af\u09be\u09a4\u09c7 \u098f\u09b0 \u0986\u0997\u09c7 \u0995\u09bf\u099b\u09c1 \u09aa\u09cb\u09b8\u09cd\u099f \u09ac\u09be \u09ac\u09be\u09a4\u09bf\u09b2 \u0995\u09b0\u09be \u09a8\u09be \u09af\u09be\u09af\u09bc"},
gMQ(){return'"\u09ac\u09bf\u09ad\u09be\u0997 \u0985\u09a8\u09c1\u09af\u09be\u09af\u09bc\u09c0 \u0996\u09b0\u099a" \u09b0\u09bf\u09aa\u09cb\u09b0\u09cd\u099f\u09c7\u09b0 \u099c\u09a8\u09cd\u09af \u0996\u09b0\u099a \u099f\u09cd\u09af\u09be\u0997 \u0995\u09b0\u09be\u09b0 \u09ac\u09bf\u09ad\u09be\u0997'},
gMT(){return"\u09b8\u09ae\u09af\u09bc\u09c7\u09b0 \u09b8\u09be\u09a5\u09c7 \u09b9\u09be\u09b0 \u09b2\u0997 \u0995\u09b0\u09c1\u09a8 \u2014 \u09ac\u09c8\u09a6\u09c7\u09b6\u09bf\u0995 \u09ae\u09c1\u09a6\u09cd\u09b0\u09be\u09b0 \u09a8\u09a5\u09bf \u09b8\u09cd\u09ac\u09af\u09bc\u0982\u0995\u09cd\u09b0\u09bf\u09af\u09bc\u09ad\u09be\u09ac\u09c7 \u09aa\u09c2\u09b0\u09a3 \u0995\u09b0\u09c7 \u098f\u09ac\u0982 \u09aa\u09c1\u09a8\u09b0\u09cd\u09ae\u09c2\u09b2\u09cd\u09af\u09be\u09af\u09bc\u09a8\u09c7 \u09b8\u09be\u09b9\u09be\u09af\u09cd\u09af \u0995\u09b0\u09c7"},
gN6(){return"\u062a\u0631\u0627\u0632\u0648\u09b0 \u0986\u0997\u09c7 \u09a8\u0997\u09a6, \u0987\u0995\u09c1\u0987\u099f\u09bf \u098f\u09ac\u0982 \u0985\u09a8\u09cd\u09af\u09be\u09a8\u09cd\u09af \u0985\u09cd\u09af\u09be\u0995\u09be\u0989\u09a8\u09cd\u099f \u0995\u09cb\u09a5\u09be\u09af\u09bc \u099b\u09bf\u09b2"},
gMN(){return"\u0995\u09cb\u09ae\u09cd\u09aa\u09be\u09a8\u09bf \u09aa\u09cd\u09b0\u09cb\u09ab\u09be\u0987\u09b2"},
gMP(){return"\u09a8\u09be\u09ae, \u09b2\u09cb\u0997\u09cb, \u09af\u09cb\u0997\u09be\u09af\u09cb\u0997\u09c7\u09b0 \u09ac\u09bf\u09ac\u09b0\u09a3, \u098f\u09ac\u0982 \u099a\u09be\u09b2\u09be\u09a8 \u09a8\u09ae\u09cd\u09ac\u09b0\u09bf\u0982 \u09aa\u09cd\u09b0\u09bf\u09ab\u09bf\u0995\u09cd\u09b8"},
gMR(){return"\u09b8\u09be\u09ae\u099e\u09cd\u099c\u09b8\u09cd\u09af\u09c7\u09b0 \u099c\u09a8\u09cd\u09af \u09b8\u09cd\u099f\u0995, \u09b2\u09c7\u099c\u09be\u09b0 \u098f\u09ac\u0982 \u0985\u09cd\u09af\u09be\u0995\u09be\u0989\u09a8\u09cd\u099f \u0995\u09cb\u09a1 \u09aa\u09b0\u09c0\u0995\u09cd\u09b7\u09be \u0995\u09b0\u09c1\u09a8 \u2014 \u098f\u09ac\u0982 \u09af\u09be \u09a0\u09bf\u0995 \u0995\u09b0\u09be \u09a8\u09bf\u09b0\u09be\u09aa\u09a6 \u09a4\u09be \u09ae\u09c7\u09b0\u09be\u09ae\u09a4 \u0995\u09b0\u09c1\u09a8"},
gMC(){return"\u0995\u09c7 \u0995\u09c0 \u0995\u09b0\u09c7\u099b\u09c7 \u2014 \u099a\u09be\u09b2\u09be\u09a8, \u09aa\u09c7\u09ae\u09c7\u09a8\u09cd\u099f, \u09ad\u09be\u0989\u099a\u09be\u09b0, \u09aa\u09bf\u09b0\u09bf\u09af\u09bc\u09a1 \u09b2\u0995 \u098f\u09ac\u0982 \u0985\u09cd\u09af\u09be\u0995\u09be\u0989\u09a8\u09cd\u099f \u09aa\u09b0\u09bf\u09ac\u09b0\u09cd\u09a4\u09a8"},
