gSK(){return"\u0627\u0633\u06d2 \u0627\u06cc\u06a9 \u0628\u0627\u0631 \u067e\u064f\u0631 \u06a9\u0631\u06cc\u06ba \u2014 \u06cc\u06c1 \u0646\u0645\u0648\u0646\u06c1 \u0644\u06d2 \u0622\u0624\u0679 \u06a9\u06cc \u0637\u0631\u062d \u06c1\u0631 \u0627\u0646\u0648\u0627\u0626\u0633 \u067e\u0631 \u0686\u06be\u067e\u062a\u0627 \u06c1\u06d2 (\u0631\u0627\u0628\u0637\u06c1 \u0634\u062e\u0635\u060c \u0639\u0645\u0627\u0631\u062a/\u06af\u0644\u06cc/\u0632\u0648\u0646\u060c \u067e\u06cc \u0627\u0648 \u0628\u0627\u06a9\u0633\u060c \u0634\u06c1\u0631\u060c \u0645\u0644\u06a9)\u06d4"},
gSR(){return"\u0628\u06cc\u0633 \u06a9\u0631\u0646\u0633\u06cc"},
gSP(){return"\u06c1\u0631 \u0631\u067e\u0648\u0631\u0679 \u0627\u0648\u0631 \u0646\u06cc\u0627 \u06a9\u0633\u0679\u0645\u0631/\u0627\u0646\u0648\u0627\u0626\u0633 \u0627\u0633 \u067e\u0631 \u0688\u06cc\u0641\u0627\u0644\u0679 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u06d4 \u0627\u0633\u06d2 \u062a\u0628\u062f\u06cc\u0644 \u06a9\u0631\u0646\u06d2 \u0633\u06d2 \u062a\u0627\u0631\u06cc\u062e\u06cc \u0627\u0639\u062f\u0627\u062f \u0648 \u0634\u0645\u0627\u0631 \u067e\u06cc\u0686\u06be\u06d2 \u062c\u0627 \u06a9\u0631 \u062a\u0628\u062f\u06cc\u0644 \u0646\u06c1\u06cc\u06ba \u06c1\u0648\u062a\u06d2 \u2014 \u0648\u06c1 \u062c\u0633 \u06a9\u0631\u0646\u0633\u06cc \u0645\u06cc\u06ba \u067e\u0648\u0633\u0679 \u06a9\u06cc\u06d2 \u06af\u0626\u06d2 \u062a\u06be\u06d2 \u0627\u0633\u06cc \u0645\u06cc\u06ba \u0631\u06c1\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"},
